?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Publicadas | TV Sumaré</title><link rel="stylesheet" href="admin.css?v=2.0.3"></head><body><div class="admin"><?php include __DIR__.'/_menu.php';?><main class="main"><div class="top"><div><span class="eyebrow">Redação</span><h1>Matérias Publicadas</h1><p class="muted">Visão administrativa do conteúdo publicado, com acesso à matéria pública e à checagem de validade.</p></div><div class="actions"><a class="btn" href="content-validity.php">Validade Editorial</a><a class="btn secondary" href="../noticias.php" target="_blank">Ver página pública</a></div></div><div class="admin-kpi-grid"><div class="admin-kpi"><span>Total publicadas</span><strong><?=count($news)?></strong></div></div><section class="box"><div class="table-wrap"><table><thead><tr><th>Data</th><th>Cidade</th><th>Categoria</th><th>Matéria</th><th>Ação</th></tr></thead><tbody><?php if(!$news):?><tr><td colspan="5">Nenhuma matéria publicada.</td></tr><?php endif;?><?php foreach(array_slice($news,0,150) as $n):?><tr><td><?=np_h(!empty($n['published_at']??$n['created_at'])?date('d/m/Y H:i',strtotime($n['published_at']??$n['created_at'])):'')?></td><td><?=np_h($n['city']??'Região')?></td><td><?=np_h($n['category']??'Notícia')?></td><td><strong><?=np_h($n['title']??'Sem título')?></strong><br><small><?=np_h($n['source']??'')?></small></td><td><a class="btn small" href="../noticia.php?id=<?=rawurlencode((string)($n['id']??''))?>" target="_blank">Abrir</a></td></tr><?php endforeach;?></tbody></table></div></section></main></div></body></html>
